const mode = $json.mode || 'propose';
const payload = $json.payload || {};
if (mode !== 'propose') return [{ json: { mode, payload, slot: $json.slot } }];

const tz = 'America/Sao_Paulo';
const now = new Date();
const dayMs = 24 * 60 * 60 * 1000;
const base = new Date(now.getTime() + dayMs);

function formatDateParts(d) {
  const fmt = new Intl.DateTimeFormat('en-CA', {
    timeZone: tz,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  });
  const parts = fmt.formatToParts(d);
  const year = parts.find(p => p.type === 'year')?.value;
  const month = parts.find(p => p.type === 'month')?.value;
  const day = parts.find(p => p.type === 'day')?.value;
  return { year, month, day };
}

function slotFor(dayOffset, hour) {
  const d = new Date(base.getTime() + dayOffset * dayMs);
  const { year, month, day } = formatDateParts(d);
  const hh = String(hour).padStart(2, '0');
  return {
    start_at: `${year}-${month}-${day}T${hh}:00:00-03:00`,
    end_at: `${year}-${month}-${day}T${String(hour + 1).padStart(2, '0')}:00:00-03:00`,
    label: `${day}/${month} às ${hh}:00`
  };
}

const slots = [slotFor(0, 10), slotFor(0, 15), slotFor(1, 10)];
return [{ json: { mode, payload, slots } }];

